contracts/GPUDexAdvancedTokenomicsV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IGPUDexTokenV2 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function burn(uint256 amount) external;
    function distributeRevenue(uint256 _rewardAmount, uint256 _feeAmount) external;
    function totalStaked() external view returns (uint256);
}

interface IPriceOracle {
    function getPrice(address token) external view returns (uint256);
    function getPlatformDemandScore() external view returns (uint256);
}

/**
 * @title GPUDexAdvancedTokenomicsV2
 * @dev Advanced tokenomics engine with dynamic APY, cross-chain features, and intelligent burn mechanisms
 */
contract GPUDexAdvancedTokenomicsV2 is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // Dynamic APY configuration
    struct DynamicAPYConfig {
        uint256 baseAPY;           // Base APY in basis points
        uint256 demandMultiplier;  // Multiplier based on platform demand
        uint256 maxAPY;            // Maximum APY cap
        uint256 minAPY;            // Minimum APY floor
        uint256 lastUpdate;       // Last update timestamp
    }

    // Cross-chain bridge information
    struct BridgeInfo {
        uint256 chainId;
        address bridgeContract;
        address tokenAddress;
        uint256 totalBridged;
        bool isActive;
        uint256 bridgeFee; // Basis points
    }

    // Burn mechanism configuration
    struct BurnMechanics {
        uint256 demandBasedBurnRate;    // Basis points
        uint256 revenueBurnRate;        // Basis points
        uint256 deflationTarget;       // Target deflation rate
        uint256 totalBurned;           // Total tokens burned
        uint256 lastBurnTime;          // Last burn execution
    }

    // Yield optimization data
    struct YieldOptimization {
        uint256 platformRevenue;       // Platform revenue in last period
        uint256 stakingParticipation;  // Staking participation rate
        uint256 optimalAPY;            // AI-calculated optimal APY
        uint256 yieldSustainabilityScore; // 0-100 sustainability score
    }

    // Institutional program configuration
    struct InstitutionalProgram {
        uint256 minimumStake;          // Minimum stake for institutions
        uint256 lockupPeriod;          // Lockup period in seconds
        uint256 bonusAPY;              // Bonus APY for institutions
        uint256 totalInstitutional;   // Total institutional stakes
        bool isActive;
    }

    // State variables
    IGPUDexTokenV2 public gpudexToken;
    IPriceOracle public priceOracle;
    
    DynamicAPYConfig public dynamicAPY;
    BurnMechanics public burnConfig;
    YieldOptimization public yieldOptim;
    InstitutionalProgram public institutional;
    
    mapping(uint256 => BridgeInfo) public bridges; // chainId => BridgeInfo
    mapping(address => uint256) public crossChainBalances;
    mapping(address => uint256) public institutionalStakes;
    mapping(address => uint256) public lastClaimTime;
    
    uint256[] public supportedChains;
    
    // Advanced metrics
    uint256 public demandScore;
    uint256 public velocityScore;
    uint256 public utilityScore;
    uint256 public sustainabilityScore;
    
    // Events
    event DynamicAPYUpdated(uint256 oldAPY, uint256 newAPY, uint256 demandScore);
    event TokensBurned(uint256 amount, string reason);
    event CrossChainBridge(address indexed user, uint256 fromChain, uint256 toChain, uint256 amount);
    event InstitutionalStakeCreated(address indexed institution, uint256 amount, uint256 bonusAPY);
    event YieldOptimizationUpdate(uint256 optimalAPY, uint256 sustainabilityScore);
    event AdvancedMetricsUpdate(uint256 demand, uint256 velocity, uint256 utility, uint256 sustainability);

    constructor(
        address _gpudexToken,
        address _priceOracle
    ) {
        gpudexToken = IGPUDexTokenV2(_gpudexToken);
        priceOracle = IPriceOracle(_priceOracle);
        
        // Initialize dynamic APY
        dynamicAPY = DynamicAPYConfig({
            baseAPY: 1000,        // 10% base APY
            demandMultiplier: 150, // 1.5x multiplier
            maxAPY: 5000,         // 50% max APY
            minAPY: 500,          // 5% min APY
            lastUpdate: block.timestamp
        });
        
        // Initialize burn mechanics
        burnConfig = BurnMechanics({
            demandBasedBurnRate: 100,    // 1% of revenue
            revenueBurnRate: 50,         // 0.5% of revenue
            deflationTarget: 200,        // 2% annual deflation target
            totalBurned: 0,
            lastBurnTime: block.timestamp
        });
        
        // Initialize institutional program
        institutional = InstitutionalProgram({
            minimumStake: 1000000 * 10**18, // 1M GPUDX minimum
            lockupPeriod: 365 days,         // 1 year lockup
            bonusAPY: 500,                  // 5% bonus APY
            totalInstitutional: 0,
            isActive: true
        });
    }

    /**
     * @dev Update dynamic APY based on platform demand and metrics
     */
    function updateDynamicAPY() external {
        require(address(priceOracle) != address(0), "Price oracle not set");
        
        // Get current demand score (0-100)
        uint256 currentScore = demandScore > 50 ? 20 : (demandScore * 20) / 50;
        
        // Calculate new APY based on demand
        uint256 baseAPY = dynamicAPY.baseAPY;
        uint256 multiplier = dynamicAPY.demandMultiplier + currentScore;
        uint256 newAPY = (baseAPY * multiplier) / 100;
        
        // Apply bounds
        if (newAPY > dynamicAPY.maxAPY) {
            newAPY = dynamicAPY.maxAPY;
        } else if (newAPY < dynamicAPY.minAPY) {
            newAPY = dynamicAPY.minAPY;
        }
        
        // Update APY in the main token contract (if accessible)
        // gpudexToken.updateAPY(newAPY); // Uncomment when function is available
        
        emit DynamicAPYUpdated(dynamicAPY.baseAPY, newAPY, currentScore);
    }

    /**
     * @dev Execute demand-based token burn
     */
    function executeDemandBasedBurn(uint256 _platformRevenue) external onlyOwner {
        require(block.timestamp >= burnConfig.lastBurnTime + 1 days, "Daily burn limit");
        
        // Calculate burn amount based on demand and revenue
        uint256 demandBurnAmount = (_platformRevenue * burnConfig.demandBasedBurnRate) / 10000;
        uint256 revenueBurnAmount = (_platformRevenue * burnConfig.revenueBurnRate) / 10000;
        
        uint256 totalBurnAmount = demandBurnAmount + revenueBurnAmount;
        
        // Ensure we don't burn more than available
        uint256 availableBalance = gpudexToken.balanceOf(address(this));
        if (totalBurnAmount > availableBalance) {
            totalBurnAmount = availableBalance;
        }
        
        if (totalBurnAmount > 0) {
            gpudexToken.burn(totalBurnAmount);
            burnConfig.totalBurned += totalBurnAmount;
            burnConfig.lastBurnTime = block.timestamp;
            
            emit TokensBurned(totalBurnAmount, "Demand-based burn");
        }
    }

    /**
     * @dev Setup cross-chain bridge
     */
    function setupCrossChainBridge(
        uint256 _chainId,
        address _bridgeContract,
        address _tokenAddress,
        uint256 _bridgeFee
    ) external onlyOwner {
        require(_bridgeFee <= 1000, "Bridge fee too high"); // Max 10%
        
        bridges[_chainId] = BridgeInfo({
            chainId: _chainId,
            bridgeContract: _bridgeContract,
            tokenAddress: _tokenAddress,
            totalBridged: 0,
            isActive: true,
            bridgeFee: _bridgeFee
        });
        
        supportedChains.push(_chainId);
    }

    /**
     * @dev Bridge tokens to another chain
     */
    function bridgeToChain(uint256 _toChainId, uint256 _amount) external nonReentrant {
        require(bridges[_toChainId].isActive, "Bridge not active");
        require(_amount > 0, "Invalid amount");
        
        BridgeInfo storage bridge = bridges[_toChainId];
        
        // Calculate bridge fee
        uint256 bridgeFee = (_amount * bridge.bridgeFee) / 10000;
        uint256 bridgeAmount = _amount - bridgeFee;
        
        // Transfer tokens from user
        gpudexToken.transfer(address(this), _amount);
        
        // Update bridge statistics
        bridge.totalBridged += bridgeAmount;
        crossChainBalances[msg.sender] += bridgeAmount;
        
        // Burn bridge fee (deflationary mechanism)
        if (bridgeFee > 0) {
            gpudexToken.burn(bridgeFee);
            emit TokensBurned(bridgeFee, "Cross-chain bridge fee");
        }
        
        emit CrossChainBridge(msg.sender, block.chainid, _toChainId, bridgeAmount);
    }

    /**
     * @dev Create institutional staking position
     */
    function createInstitutionalStake(uint256 _amount) external nonReentrant {
        require(institutional.isActive, "Institutional program not active");
        require(_amount >= institutional.minimumStake, "Below minimum stake");
        
        // Transfer tokens to contract
        gpudexToken.transfer(address(this), _amount);
        
        // Record institutional stake
        institutionalStakes[msg.sender] += _amount;
        institutional.totalInstitutional += _amount;
        
        emit InstitutionalStakeCreated(msg.sender, _amount, institutional.bonusAPY);
    }

    /**
     * @dev Calculate optimal yield and sustainability score
     * @return optimalAPY The calculated optimal APY
     * @return sustainability The sustainability score (0-100)
     */
    function calculateOptimalYield() external view returns (uint256 optimalAPY, uint256 sustainability) {
        // Get platform metrics
        uint256 totalStaked = gpudexToken.totalSupply() / 4; // Assume 25% staked
        uint256 platformRevenue = address(this).balance; // Simple revenue proxy
        
        // Calculate optimal APY based on staking participation and revenue
        uint256 stakingParticipation = totalStaked > 0 ? (totalStaked * 100) / gpudexToken.totalSupply() : 0;
        
        // Target 30-50% staking participation
        if (stakingParticipation < 30) {
            optimalAPY = dynamicAPY.maxAPY; // High APY to attract stakers
        } else if (stakingParticipation > 50) {
            optimalAPY = dynamicAPY.minAPY; // Lower APY when over-staked
        } else {
            // Linear interpolation between min and max
            uint256 range = dynamicAPY.maxAPY - dynamicAPY.minAPY;
            uint256 factor = (50 - stakingParticipation) * 100 / 20; // 20% range
            optimalAPY = dynamicAPY.minAPY + (range * factor / 100);
        }
        
        // Calculate sustainability (higher revenue = higher sustainability)
        sustainability = platformRevenue > 1 ether ? 100 : (platformRevenue * 100) / 1 ether;
        if (sustainability > 100) sustainability = 100;
        
        return (optimalAPY, sustainability);
    }

    /**
     * @dev Update platform metrics and recalculate tokenomics
     * @param _platformRevenue Current platform revenue
     * @param _stakingParticipation Current staking participation rate (basis points)
     */
    function updatePlatformMetrics(uint256 _platformRevenue, uint256 _stakingParticipation) external onlyOwner {
        // Calculate optimal APY and sustainability
        (uint256 optimalAPY, uint256 sustainabilityValue) = this.calculateOptimalYield();
        
        // Update dynamic APY if needed
        if (optimalAPY != dynamicAPY.baseAPY) {
            dynamicAPY.baseAPY = optimalAPY;
            emit DynamicAPYUpdated(dynamicAPY.baseAPY, optimalAPY, demandScore);
        }
        
        // Update advanced metrics
        this.updateAdvancedMetrics();
        
        emit YieldOptimizationUpdate(optimalAPY, sustainabilityValue);
    }

    /**
     * @dev Calculate and update advanced metrics
     */
    function updateAdvancedMetrics() external {
        // Calculate demand score based on recent activity
        uint256 currentScore = demandScore > 50 ? 20 : (demandScore * 20) / 50;
        
        // Update velocity score
        uint256 currentVelocity = gpudexToken.totalSupply() > 0 ? 
            (address(gpudexToken).balance * 10000) / gpudexToken.totalSupply() : 0;
        velocityScore = currentVelocity > 10000 ? 10000 : currentVelocity;
        
        // Update utility score (simplified calculation)
        utilityScore = (currentScore + velocityScore) / 2;
        if (utilityScore > 10000) utilityScore = 10000;
        
        // Update sustainability score
        sustainabilityScore = utilityScore > 5000 ? 10000 : (utilityScore * 2);
        
        emit AdvancedMetricsUpdate(currentScore, velocityScore, utilityScore, sustainabilityScore);
    }

    /**
     * @dev Internal function to calculate velocity score
     */
    function _calculateVelocityScore() internal view returns (uint256) {
        // Simplified velocity calculation
        // In production, would use transaction count and volume data
        uint256 totalSupply = gpudexToken.totalSupply();
        uint256 totalStaked = gpudexToken.totalStaked();
        
        if (totalSupply == 0) return 0;
        
        uint256 circulatingSupply = totalSupply - totalStaked;
        uint256 velocityRatio = totalStaked > 0 ? (circulatingSupply * 100) / totalStaked : 100;
        
        return velocityRatio > 100 ? 100 : velocityRatio;
    }

    /**
     * @dev Internal function to calculate utility score
     */
    function _calculateUtilityScore() internal view returns (uint256) {
        // Utility score based on burns, platform usage, and real transactions
        uint256 burnScore = burnConfig.totalBurned > 0 ? 40 : 0;
        uint256 revenueScore = yieldOptim.platformRevenue > 0 ? 40 : 0;
        uint256 currentDemandScore = demandScore > 50 ? 20 : (demandScore * 20) / 50;
        
        return burnScore + revenueScore + demandScore;
    }

    /**
     * @dev Get current dynamic APY
     */
    function getCurrentAPY() external view returns (uint256) {
        return dynamicAPY.baseAPY;
    }

    /**
     * @dev Get burn statistics
     */
    function getBurnStatistics() external view returns (
        uint256 totalBurned,
        uint256 burnRate,
        uint256 deflationRate
    ) {
        totalBurned = burnConfig.totalBurned;
        burnRate = burnConfig.demandBasedBurnRate + burnConfig.revenueBurnRate;
        
        uint256 totalSupply = gpudexToken.totalSupply();
        deflationRate = totalSupply > 0 ? (totalBurned * 10000) / totalSupply : 0;
        
        return (totalBurned, burnRate, deflationRate);
    }

    /**
     * @dev Get cross-chain bridge information
     */
    function getBridgeInfo(uint256 _chainId) external view returns (BridgeInfo memory) {
        return bridges[_chainId];
    }

    /**
     * @dev Get supported chains
     */
    function getSupportedChains() external view returns (uint256[] memory) {
        return supportedChains;
    }

    /**
     * @dev Get institutional staking information
     */
    function getInstitutionalInfo() external view returns (InstitutionalProgram memory) {
        return institutional;
    }

    /**
     * @dev Get user's institutional stake
     */
    function getInstitutionalStake(address _user) external view returns (uint256) {
        return institutionalStakes[_user];
    }

    /**
     * @dev Update dynamic APY configuration
     */
    function updateDynamicAPYConfig(
        uint256 _baseAPY,
        uint256 _demandMultiplier,
        uint256 _maxAPY,
        uint256 _minAPY
    ) external onlyOwner {
        require(_maxAPY > _minAPY, "Invalid APY bounds");
        require(_maxAPY <= 10000, "APY too high"); // Max 100%
        
        dynamicAPY.baseAPY = _baseAPY;
        dynamicAPY.demandMultiplier = _demandMultiplier;
        dynamicAPY.maxAPY = _maxAPY;
        dynamicAPY.minAPY = _minAPY;
    }

    /**
     * @dev Update burn configuration
     */
    function updateBurnConfig(
        uint256 _demandBasedBurnRate,
        uint256 _revenueBurnRate,
        uint256 _deflationTarget
    ) external onlyOwner {
        require(_demandBasedBurnRate <= 1000, "Burn rate too high"); // Max 10%
        require(_revenueBurnRate <= 1000, "Burn rate too high"); // Max 10%
        
        burnConfig.demandBasedBurnRate = _demandBasedBurnRate;
        burnConfig.revenueBurnRate = _revenueBurnRate;
        burnConfig.deflationTarget = _deflationTarget;
    }

    /**
     * @dev Emergency functions
     */
    function pauseBridge(uint256 _chainId) external onlyOwner {
        bridges[_chainId].isActive = false;
    }

    function unpauseBridge(uint256 _chainId) external onlyOwner {
        bridges[_chainId].isActive = true;
    }

    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).safeTransfer(owner(), _amount);
    }
}

contracts/GPUDexEnterpriseV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IGPUDexTokenV2 {
    function processGPURental(address _user, uint256 _amount) external returns (uint256 discountAmount);
    function getUserTierInfo(address _user) external view returns (uint8 tier, uint256 stakedAmount, uint256 minStakeForNextTier, uint256 apyBasisPoints, uint256 gpuDiscountBasisPoints, uint256 providerBoostBasisPoints);
    function distributeRevenue(uint256 _rewardAmount, uint256 _feeAmount) external;
}

/**
 * @title GPUDexEnterpriseV2
 * @dev Enterprise-focused contract for B2B client management and revenue optimization
 */
contract GPUDexEnterpriseV2 is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // Enterprise client tiers
    enum EnterpriseTier { STARTUP, GROWTH, PROFESSIONAL, ENTERPRISE, PLATINUM }

    // Contract types
    enum ContractType { PAYPERUSE, MONTHLY, QUARTERLY, ANNUAL, CUSTOM }

    struct EnterpriseClient {
        address clientAddress;
        string companyName;
        string contactEmail;
        EnterpriseTier tier;
        ContractType contractType;
        uint256 volumeDiscount; // Basis points (100 = 1%)
        uint256 monthlyCommitment; // Minimum monthly spend in USD
        uint256 totalSpent;
        uint256 totalHours;
        uint256 joinedAt;
        bool isActive;
        bool hasCustomPricing;
        uint256 customPricePerHour; // Custom rate in wei
    }

    struct InstitutionalStaking {
        address institution;
        uint256 stakedAmount;
        uint256 lockPeriod; // In days
        uint256 customAPY; // Basis points
        uint256 stakedAt;
        uint256 lockedUntil;
        bool isActive;
        string institutionName;
        uint256 minimumStake;
    }

    struct RevenueShare {
        address recipient;
        uint256 sharePercentage; // Basis points
        uint256 totalReceived;
        bool isActive;
    }

    // State variables
    mapping(address => EnterpriseClient) public enterpriseClients;
    mapping(address => InstitutionalStaking) public institutionalStaking;
    mapping(address => RevenueShare) public revenueShares;
    
    address[] public clientList;
    address[] public institutionList;
    
    IGPUDexTokenV2 public gpudexToken;
    
    // Platform metrics
    uint256 public totalEnterpriseRevenue;
    uint256 public totalInstitutionalStaked;
    uint256 public activeEnterpriseClients;
    uint256 public totalRevenueShared;
    
    // Pricing configuration
    mapping(EnterpriseTier => uint256) public tierDiscounts; // Basis points
    mapping(EnterpriseTier => uint256) public tierMinimums; // Minimum monthly spend
    
    uint256 public baseGPUPricePerHour = 50000000000000000; // 0.05 ETH base price
    uint256 public platformFeePercent = 300; // 3%
    uint256 public maxVolumeDiscount = 5000; // 50% max discount
    
    // Events
    event EnterpriseClientRegistered(address indexed client, string companyName, EnterpriseTier tier);
    event ContractUpgraded(address indexed client, EnterpriseTier oldTier, EnterpriseTier newTier);
    event InstitutionalStakingCreated(address indexed institution, uint256 amount, uint256 customAPY);
    event EnterpriseRentalProcessed(address indexed client, uint256 amount, uint256 discount, uint256 rentalHours);
    event RevenueShareDistributed(address indexed recipient, uint256 amount);
    event CustomPricingSet(address indexed client, uint256 customPrice);

    constructor(address _gpudexToken) {
        gpudexToken = IGPUDexTokenV2(_gpudexToken);
        
        // Initialize tier discounts
        tierDiscounts[EnterpriseTier.STARTUP] = 500;     // 5%
        tierDiscounts[EnterpriseTier.GROWTH] = 1000;     // 10%
        tierDiscounts[EnterpriseTier.PROFESSIONAL] = 1500; // 15%
        tierDiscounts[EnterpriseTier.ENTERPRISE] = 2000;   // 20%
        tierDiscounts[EnterpriseTier.PLATINUM] = 3000;     // 30%
        
        // Initialize tier minimums (in USD, scaled by 1e18)
        tierMinimums[EnterpriseTier.STARTUP] = 1000 * 1e18;      // $1,000
        tierMinimums[EnterpriseTier.GROWTH] = 5000 * 1e18;       // $5,000
        tierMinimums[EnterpriseTier.PROFESSIONAL] = 25000 * 1e18; // $25,000
        tierMinimums[EnterpriseTier.ENTERPRISE] = 100000 * 1e18;  // $100,000
        tierMinimums[EnterpriseTier.PLATINUM] = 500000 * 1e18;    // $500,000
    }

    /**
     * @dev Register a new enterprise client
     */
    function registerEnterpriseClient(
        string memory _companyName,
        string memory _contactEmail,
        EnterpriseTier _tier,
        ContractType _contractType
    ) external returns (bool) {
        require(!enterpriseClients[msg.sender].isActive, "Client already registered");
        require(bytes(_companyName).length > 0, "Company name required");
        
        enterpriseClients[msg.sender] = EnterpriseClient({
            clientAddress: msg.sender,
            companyName: _companyName,
            contactEmail: _contactEmail,
            tier: _tier,
            contractType: _contractType,
            volumeDiscount: tierDiscounts[_tier],
            monthlyCommitment: tierMinimums[_tier],
            totalSpent: 0,
            totalHours: 0,
            joinedAt: block.timestamp,
            isActive: true,
            hasCustomPricing: false,
            customPricePerHour: 0
        });
        
        clientList.push(msg.sender);
        activeEnterpriseClients++;
        
        emit EnterpriseClientRegistered(msg.sender, _companyName, _tier);
        return true;
    }

    /**
     * @dev Process enterprise GPU rental with custom pricing
     */
    function processEnterpriseRental(
        address _client,
        uint256 _hours,
        string memory _gpuType
    ) external onlyOwner nonReentrant returns (uint256 totalCost, uint256 discount) {
        require(enterpriseClients[_client].isActive, "Client not active");
        
        EnterpriseClient storage client = enterpriseClients[_client];
        
        // Calculate base cost
        uint256 baseCost = client.hasCustomPricing ? 
            client.customPricePerHour * _hours : 
            baseGPUPricePerHour * _hours;
        
        // Apply enterprise tier discount
        discount = (baseCost * client.volumeDiscount) / 10000;
        
        // Apply additional GPUDX token discount if client has staked tokens
        uint256 additionalDiscount = gpudexToken.processGPURental(_client, baseCost - discount);
        discount += additionalDiscount;
        
        totalCost = baseCost - discount;
        
        // Update client statistics
        client.totalSpent += totalCost;
        client.totalHours += _hours;
        totalEnterpriseRevenue += totalCost;
        
        // Check for tier upgrade eligibility
        _checkTierUpgrade(_client);
        
        emit EnterpriseRentalProcessed(_client, totalCost, discount, _hours);
        
        return (totalCost, discount);
    }

    /**
     * @dev Create institutional staking program
     */
    function createInstitutionalStaking(
        address _institution,
        string memory _institutionName,
        uint256 _customAPY,
        uint256 _lockPeriodDays,
        uint256 _minimumStake
    ) external onlyOwner {
        require(_customAPY <= 10000, "APY too high"); // Max 100%
        require(_lockPeriodDays >= 30, "Minimum 30 days lock");
        require(_minimumStake >= 100000 * 10**18, "Minimum 100K tokens"); // 100K GPUDX minimum
        
        institutionalStaking[_institution] = InstitutionalStaking({
            institution: _institution,
            stakedAmount: 0,
            lockPeriod: _lockPeriodDays,
            customAPY: _customAPY,
            stakedAt: 0,
            lockedUntil: 0,
            isActive: true,
            institutionName: _institutionName,
            minimumStake: _minimumStake
        });
        
        institutionList.push(_institution);
        
        emit InstitutionalStakingCreated(_institution, _minimumStake, _customAPY);
    }

    /**
     * @dev Institution stakes tokens with custom terms
     */
    function stakeInstitutional(uint256 _amount) external nonReentrant {
        InstitutionalStaking storage staking = institutionalStaking[msg.sender];
        require(staking.isActive, "Institution not registered");
        require(_amount >= staking.minimumStake, "Below minimum stake");
        
        // Transfer tokens to this contract
        IERC20(address(gpudexToken)).safeTransferFrom(msg.sender, address(this), _amount);
        
        staking.stakedAmount += _amount;
        staking.stakedAt = block.timestamp;
        staking.lockedUntil = block.timestamp + (staking.lockPeriod * 1 days);
        
        totalInstitutionalStaked += _amount;
    }

    /**
     * @dev Set custom pricing for enterprise client
     */
    function setCustomPricing(address _client, uint256 _customPricePerHour) external onlyOwner {
        require(enterpriseClients[_client].isActive, "Client not active");
        require(_customPricePerHour > 0, "Invalid price");
        
        enterpriseClients[_client].hasCustomPricing = true;
        enterpriseClients[_client].customPricePerHour = _customPricePerHour;
        
        emit CustomPricingSet(_client, _customPricePerHour);
    }

    /**
     * @dev Setup revenue sharing for partners
     */
    function setupRevenueShare(address _recipient, uint256 _sharePercentage) external onlyOwner {
        require(_sharePercentage <= 1000, "Max 10% share"); // Max 10%
        
        revenueShares[_recipient] = RevenueShare({
            recipient: _recipient,
            sharePercentage: _sharePercentage,
            totalReceived: 0,
            isActive: true
        });
    }

    /**
     * @dev Distribute revenue to share holders
     */
    function distributeRevenueShares(uint256 _totalRevenue) external onlyOwner {
        // This would iterate through revenue share recipients
        // Simplified for gas efficiency
        uint256 platformShare = (_totalRevenue * 7000) / 10000; // 70% to platform
        uint256 stakingRewards = (_totalRevenue * 3000) / 10000; // 30% to staking rewards
        
        // Distribute to GPUDX staking rewards
        gpudexToken.distributeRevenue(stakingRewards, 0);
        
        totalRevenueShared += stakingRewards;
    }

    /**
     * @dev Check and upgrade client tier based on spending
     */
    function _checkTierUpgrade(address _client) internal {
        EnterpriseClient storage client = enterpriseClients[_client];
        EnterpriseTier currentTier = client.tier;
        EnterpriseTier newTier = currentTier;
        
        // Check tier upgrade eligibility based on total spending
        if (client.totalSpent >= tierMinimums[EnterpriseTier.PLATINUM] && currentTier != EnterpriseTier.PLATINUM) {
            newTier = EnterpriseTier.PLATINUM;
        } else if (client.totalSpent >= tierMinimums[EnterpriseTier.ENTERPRISE] && uint8(currentTier) < uint8(EnterpriseTier.ENTERPRISE)) {
            newTier = EnterpriseTier.ENTERPRISE;
        } else if (client.totalSpent >= tierMinimums[EnterpriseTier.PROFESSIONAL] && uint8(currentTier) < uint8(EnterpriseTier.PROFESSIONAL)) {
            newTier = EnterpriseTier.PROFESSIONAL;
        } else if (client.totalSpent >= tierMinimums[EnterpriseTier.GROWTH] && uint8(currentTier) < uint8(EnterpriseTier.GROWTH)) {
            newTier = EnterpriseTier.GROWTH;
        }
        
        if (newTier != currentTier) {
            client.tier = newTier;
            client.volumeDiscount = tierDiscounts[newTier];
            emit ContractUpgraded(_client, currentTier, newTier);
        }
    }

    /**
     * @dev Get enterprise client details
     */
    function getEnterpriseClient(address _client) external view returns (EnterpriseClient memory) {
        return enterpriseClients[_client];
    }

    /**
     * @dev Get institutional staking details
     */
    function getInstitutionalStaking(address _institution) external view returns (InstitutionalStaking memory) {
        return institutionalStaking[_institution];
    }

    /**
     * @dev Calculate enterprise pricing for quote
     */
    function calculateEnterpriseQuote(
        address _client,
        uint256 _hours,
        string memory _gpuType
    ) external view returns (uint256 baseCost, uint256 discount, uint256 finalCost) {
        if (!enterpriseClients[_client].isActive) {
            baseCost = baseGPUPricePerHour * _hours;
            discount = 0;
            finalCost = baseCost;
            return (baseCost, discount, finalCost);
        }
        
        EnterpriseClient memory client = enterpriseClients[_client];
        
        baseCost = client.hasCustomPricing ? 
            client.customPricePerHour * _hours : 
            baseGPUPricePerHour * _hours;
        
        discount = (baseCost * client.volumeDiscount) / 10000;
        finalCost = baseCost - discount;
        
        return (baseCost, discount, finalCost);
    }

    /**
     * @dev Get platform enterprise metrics
     */
    function getEnterpriseMetrics() external view returns (
        uint256 totalRevenue,
        uint256 totalClients,
        uint256 totalInstitutionalStaking,
        uint256 averageClientValue
    ) {
        totalRevenue = totalEnterpriseRevenue;
        totalClients = activeEnterpriseClients;
        totalInstitutionalStaking = totalInstitutionalStaked;
        averageClientValue = totalClients > 0 ? totalRevenue / totalClients : 0;
    }

    /**
     * @dev Update base pricing
     */
    function updateBasePricing(uint256 _newBasePrice) external onlyOwner {
        require(_newBasePrice > 0, "Invalid price");
        baseGPUPricePerHour = _newBasePrice;
    }

    /**
     * @dev Update tier discounts
     */
    function updateTierDiscount(EnterpriseTier _tier, uint256 _discount) external onlyOwner {
        require(_discount <= maxVolumeDiscount, "Discount too high");
        tierDiscounts[_tier] = _discount;
    }

    /**
     * @dev Emergency withdraw
     */
    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).safeTransfer(owner(), _amount);
    }
}

contracts/GPUDexEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title GPUDexEscrow
 * @dev Decentralized escrow system for GPU rentals
 * Holds payments until service delivery is confirmed
 */
contract GPUDexEscrow is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;
    
    // Rental states
    enum RentalState {
        Created,        // Initial state
        Funded,         // Payment deposited
        Active,         // GPU access provided
        Completed,      // Service delivered successfully
        Disputed,       // Dispute raised
        Resolved,       // Dispute resolved
        Cancelled,      // Rental cancelled
        Refunded        // Payment refunded
    }
    
    // Dispute reasons
    enum DisputeReason {
        NoAccess,           // Provider didn't provide access
        PoorPerformance,    // GPU performance issues
        Downtime,           // Unexpected downtime
        Other               // Other reasons
    }
    
    struct Rental {
        uint256 rentalId;
        address renter;
        address provider;
        string gpuType;
        uint256 pricePerHour;
        uint256 duration; // Duration in hours
        uint256 totalAmount;
        uint256 depositAmount;
        address paymentToken;       // ERC20 token (USDC, USDT, etc.)
        RentalState state;
        uint256 createdAt;
        uint256 startedAt;
        uint256 completedAt;
        uint256 disputeDeadline;
        string providerEndpoint;    // SSH/API endpoint for access
        string accessCredentials;   // Encrypted access credentials
        bool autoRelease;          // Auto-release after period
    }
    
    struct Dispute {
        uint256 rentalId;
        address initiator;
        DisputeReason reason;
        string description;
        uint256 createdAt;
        uint256 resolvedAt;
        address arbitrator;
        uint256 refundAmount;      // Amount to refund to renter
        uint256 paymentAmount;     // Amount to pay to provider
        bool resolved;
    }
    
    // State variables
    mapping(uint256 => Rental) public rentals;
    mapping(uint256 => Dispute) public disputes;
    mapping(address => bool) public authorizedArbitrators;
    mapping(address => uint256) public providerStakes;
    mapping(address => uint256[]) public renterRentals;
    mapping(address => uint256[]) public providerRentals;
    
    uint256 public nextRentalId = 1;
    uint256 public platformFeePercent = 300; // 3% (300 basis points)
    uint256 public disputePeriod = 24 hours;
    uint256 public autoReleaseDelay = 48 hours;
    uint256 public minimumStake = 1000 * 10**18; // 1000 tokens minimum stake
    
    address public feeRecipient;
    address public gpudexToken; // Platform token for staking
    
    // Events
    event RentalCreated(
        uint256 indexed rentalId,
        address indexed renter,
        address indexed provider,
        string gpuType,
        uint256 totalAmount
    );
    
    event RentalFunded(uint256 indexed rentalId, uint256 amount);
    event RentalStarted(uint256 indexed rentalId, string accessInfo);
    event RentalCompleted(uint256 indexed rentalId);
    event RentalCancelled(uint256 indexed rentalId);
    
    event DisputeCreated(
        uint256 indexed rentalId,
        address indexed initiator,
        DisputeReason reason
    );
    
    event DisputeResolved(
        uint256 indexed rentalId,
        uint256 refundAmount,
        uint256 paymentAmount
    );
    
    event ProviderStaked(address indexed provider, uint256 amount);
    event ProviderUnstaked(address indexed provider, uint256 amount);
    event ProviderSlashed(address indexed provider, uint256 amount);
    
    modifier onlyRenter(uint256 _rentalId) {
        require(rentals[_rentalId].renter == msg.sender, "Not the renter");
        _;
    }
    
    modifier onlyProvider(uint256 _rentalId) {
        require(rentals[_rentalId].provider == msg.sender, "Not the provider");
        _;
    }
    
    modifier onlyArbitrator() {
        require(authorizedArbitrators[msg.sender], "Not authorized arbitrator");
        _;
    }
    
    modifier inState(uint256 _rentalId, RentalState _state) {
        require(rentals[_rentalId].state == _state, "Invalid rental state");
        _;
    }
    
    constructor(address _feeRecipient, address _gpudexToken) {
        feeRecipient = _feeRecipient;
        gpudexToken = _gpudexToken;
        authorizedArbitrators[msg.sender] = true;
    }
    
    /**
     * @dev Create a new GPU rental
     */
    function createRental(
        address _provider,
        string memory _gpuType,
        uint256 _pricePerHour,
        uint256 _duration,
        address _paymentToken,
        bool _autoRelease
    ) external returns (uint256) {
        require(_provider != address(0), "Invalid provider");
        require(_provider != msg.sender, "Cannot rent from yourself");
        require(_pricePerHour > 0, "Invalid price");
        require(_duration > 0, "Invalid duration");
        require(providerStakes[_provider] >= minimumStake, "Provider not staked");
        
        uint256 totalAmount = _pricePerHour * _duration;
        uint256 depositAmount = totalAmount + (totalAmount * 20 / 100); // 20% security deposit
        
        uint256 rentalId = nextRentalId++;
        
        rentals[rentalId] = Rental({
            rentalId: rentalId,
            renter: msg.sender,
            provider: _provider,
            gpuType: _gpuType,
            pricePerHour: _pricePerHour,
            duration: _duration,
            totalAmount: totalAmount,
            depositAmount: depositAmount,
            paymentToken: _paymentToken,
            state: RentalState.Created,
            createdAt: block.timestamp,
            startedAt: 0,
            completedAt: 0,
            disputeDeadline: 0,
            providerEndpoint: "",
            accessCredentials: "",
            autoRelease: _autoRelease
        });
        
        renterRentals[msg.sender].push(rentalId);
        providerRentals[_provider].push(rentalId);
        
        emit RentalCreated(rentalId, msg.sender, _provider, _gpuType, totalAmount);
        
        return rentalId;
    }
    
    /**
     * @dev Fund a rental with payment
     */
    function fundRental(uint256 _rentalId) 
        external 
        onlyRenter(_rentalId)
        inState(_rentalId, RentalState.Created)
        nonReentrant
    {
        Rental storage rental = rentals[_rentalId];
        
        // Transfer payment tokens to escrow
        IERC20(rental.paymentToken).safeTransferFrom(
            msg.sender,
            address(this),
            rental.depositAmount
        );
        
        rental.state = RentalState.Funded;
        
        emit RentalFunded(_rentalId, rental.depositAmount);
    }
    
    /**
     * @dev Provider starts the rental and provides access
     */
    function startRental(
        uint256 _rentalId,
        string memory _providerEndpoint,
        string memory _accessCredentials
    ) 
        external 
        onlyProvider(_rentalId)
        inState(_rentalId, RentalState.Funded)
    {
        Rental storage rental = rentals[_rentalId];
        
        rental.state = RentalState.Active;
        rental.startedAt = block.timestamp;
        rental.disputeDeadline = block.timestamp + disputePeriod;
        rental.providerEndpoint = _providerEndpoint;
        rental.accessCredentials = _accessCredentials;
        
        emit RentalStarted(_rentalId, _providerEndpoint);
    }
    
    /**
     * @dev Complete rental and release payment
     */
    function completeRental(uint256 _rentalId) 
        external
        nonReentrant
    {
        Rental storage rental = rentals[_rentalId];
        
        require(
            rental.state == RentalState.Active,
            "Rental not active"
        );
        
        require(
            msg.sender == rental.renter || 
            msg.sender == rental.provider ||
            (rental.autoRelease && block.timestamp >= rental.disputeDeadline),
            "Not authorized to complete"
        );
        
        // If auto-release and past deadline, or manual completion
        if (block.timestamp >= rental.disputeDeadline || msg.sender == rental.renter) {
            _releasePayment(_rentalId);
        }
    }
    
    /**
     * @dev Create a dispute
     */
    function createDispute(
        uint256 _rentalId,
        DisputeReason _reason,
        string memory _description
    ) 
        external
        onlyRenter(_rentalId)
        inState(_rentalId, RentalState.Active)
    {
        require(block.timestamp <= rentals[_rentalId].disputeDeadline, "Dispute period expired");
        
        disputes[_rentalId] = Dispute({
            rentalId: _rentalId,
            initiator: msg.sender,
            reason: _reason,
            description: _description,
            createdAt: block.timestamp,
            resolvedAt: 0,
            arbitrator: address(0),
            refundAmount: 0,
            paymentAmount: 0,
            resolved: false
        });
        
        rentals[_rentalId].state = RentalState.Disputed;
        
        emit DisputeCreated(_rentalId, msg.sender, _reason);
    }
    
    /**
     * @dev Resolve dispute (arbitrator only)
     */
    function resolveDispute(
        uint256 _rentalId,
        uint256 _refundAmount,
        uint256 _paymentAmount
    ) 
        external
        onlyArbitrator
        inState(_rentalId, RentalState.Disputed)
        nonReentrant
    {
        Rental storage rental = rentals[_rentalId];
        Dispute storage dispute = disputes[_rentalId];
        
        require(_refundAmount + _paymentAmount <= rental.depositAmount, "Invalid amounts");
        
        dispute.arbitrator = msg.sender;
        dispute.refundAmount = _refundAmount;
        dispute.paymentAmount = _paymentAmount;
        dispute.resolvedAt = block.timestamp;
        dispute.resolved = true;
        
        rental.state = RentalState.Resolved;
        
        // Transfer refund to renter
        if (_refundAmount > 0) {
            IERC20(rental.paymentToken).safeTransfer(rental.renter, _refundAmount);
        }
        
        // Transfer payment to provider
        if (_paymentAmount > 0) {
            uint256 platformFee = _paymentAmount * platformFeePercent / 10000;
            uint256 providerAmount = _paymentAmount - platformFee;
            
            IERC20(rental.paymentToken).safeTransfer(rental.provider, providerAmount);
            IERC20(rental.paymentToken).safeTransfer(feeRecipient, platformFee);
        }
        
        // Remaining amount goes to platform (penalty)
        uint256 remaining = rental.depositAmount - _refundAmount - _paymentAmount;
        if (remaining > 0) {
            IERC20(rental.paymentToken).safeTransfer(feeRecipient, remaining);
        }
        
        emit DisputeResolved(_rentalId, _refundAmount, _paymentAmount);
    }
    
    /**
     * @dev Cancel unfunded rental
     */
    function cancelRental(uint256 _rentalId) 
        external
        inState(_rentalId, RentalState.Created)
    {
        require(
            msg.sender == rentals[_rentalId].renter || 
            msg.sender == rentals[_rentalId].provider,
            "Not authorized"
        );
        
        rentals[_rentalId].state = RentalState.Cancelled;
        
        emit RentalCancelled(_rentalId);
    }
    
    /**
     * @dev Stake tokens as a provider
     */
    function stakeAsProvider(uint256 _amount) external nonReentrant {
        require(_amount >= minimumStake, "Amount below minimum stake");
        
        IERC20(gpudexToken).safeTransferFrom(msg.sender, address(this), _amount);
        providerStakes[msg.sender] += _amount;
        
        emit ProviderStaked(msg.sender, _amount);
    }
    
    /**
     * @dev Unstake tokens (with delay for security)
     */
    function unstakeProvider(uint256 _amount) external nonReentrant {
        require(providerStakes[msg.sender] >= _amount, "Insufficient stake");
        require(providerStakes[msg.sender] - _amount >= minimumStake, "Must maintain minimum stake");
        
        providerStakes[msg.sender] -= _amount;
        IERC20(gpudexToken).safeTransfer(msg.sender, _amount);
        
        emit ProviderUnstaked(msg.sender, _amount);
    }
    
    /**
     * @dev Internal function to release payment
     */
    function _releasePayment(uint256 _rentalId) internal {
        Rental storage rental = rentals[_rentalId];
        
        rental.state = RentalState.Completed;
        rental.completedAt = block.timestamp;
        
        // Calculate fees
        uint256 platformFee = rental.totalAmount * platformFeePercent / 10000;
        uint256 providerAmount = rental.totalAmount - platformFee;
        uint256 refundAmount = rental.depositAmount - rental.totalAmount;
        
        // Transfer payment to provider
        IERC20(rental.paymentToken).safeTransfer(rental.provider, providerAmount);
        
        // Transfer platform fee
        IERC20(rental.paymentToken).safeTransfer(feeRecipient, platformFee);
        
        // Refund security deposit
        IERC20(rental.paymentToken).safeTransfer(rental.renter, refundAmount);
        
        emit RentalCompleted(_rentalId);
    }
    
    /**
     * @dev Add authorized arbitrator
     */
    function addArbitrator(address _arbitrator) external onlyOwner {
        authorizedArbitrators[_arbitrator] = true;
    }
    
    /**
     * @dev Remove arbitrator
     */
    function removeArbitrator(address _arbitrator) external onlyOwner {
        authorizedArbitrators[_arbitrator] = false;
    }
    
    /**
     * @dev Update platform fee
     */
    function updatePlatformFee(uint256 _feePercent) external onlyOwner {
        require(_feePercent <= 1000, "Fee too high"); // Max 10%
        platformFeePercent = _feePercent;
    }
    
    /**
     * @dev Emergency withdrawal (owner only)
     */
    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).safeTransfer(owner(), _amount);
    }
    
    /**
     * @dev Get rental details
     */
    function getRental(uint256 _rentalId) external view returns (Rental memory) {
        return rentals[_rentalId];
    }
    
    /**
     * @dev Get user rentals
     */
    function getUserRentals(address _user, bool _asRenter) external view returns (uint256[] memory) {
        return _asRenter ? renterRentals[_user] : providerRentals[_user];
    }
    
    /**
     * @dev Get provider stake amount
     */
    function getProviderStake(address _provider) external view returns (uint256) {
        return providerStakes[_provider];
    }
}

contracts/GPUDexEscrowV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IGPUDexTokenV2 {
    function processGPURental(address _user, uint256 _amount) external returns (uint256 discountAmount);
    function processProviderEarnings(address _provider, uint256 _baseAmount) external returns (uint256 totalAmount);
    function awardSocialReward(address _user, string memory _activity, uint256 _amount) external;
    function processReferral(address _referrer, address _referee, uint256 _rewardAmount) external;
    function getUserTierInfo(address _user) external view returns (uint8 tier, uint256 stakedAmount, uint256 minStakeForNextTier, uint256 apyBasisPoints, uint256 gpuDiscountBasisPoints, uint256 providerBoostBasisPoints);
}

/**
 * @title GPUDexEscrowV2
 * @dev Enhanced escrow system with comprehensive utility validation and social gamification
 */
contract GPUDexEscrowV2 is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;
    
    // Rental states
    enum RentalState {
        Created,        // Initial state
        Funded,         // Payment deposited
        Active,         // GPU access provided
        Completed,      // Service delivered successfully
        Disputed,       // Dispute raised
        Resolved,       // Dispute resolved
        Cancelled,      // Rental cancelled
        Refunded        // Payment refunded
    }
    
    // GPU performance tiers
    enum GPUTier {
        BASIC,      // GTX/RTX 3060, etc.
        GAMING,     // RTX 3070/4060, etc.
        PRO,        // RTX 3080/4070, etc.
        ENTERPRISE, // RTX 4080/4090, A100, etc.
        DATACENTER  // H100, A100 clusters, etc.
    }
    
    struct Rental {
        uint256 rentalId;
        address renter;
        address provider;
        string gpuType;
        GPUTier gpuTier;
        uint256 pricePerHour;
        uint256 duration; // Duration in hours
        uint256 totalAmount;
        uint256 depositAmount;
        uint256 discountApplied; // GPUDX discount amount
        address paymentToken;
        RentalState state;
        uint256 createdAt;
        uint256 startedAt;
        uint256 completedAt;
        uint256 disputeDeadline;
        string providerEndpoint;
        string accessCredentials;
        bool autoRelease;
        uint256 performanceScore; // 1-100 rating
        bool paidWithGPUDX; // If rental was paid with GPUDX tokens
    }
    
    struct ProviderStats {
        uint256 totalRentals;
        uint256 totalEarnings;
        uint256 totalHours;
        uint256 averagePerformance;
        uint256 lastActiveAt;
        uint256 stakingTier;
        bool isVerified;
    }
    
    struct UserStats {
        uint256 totalSpent;
        uint256 totalHours;
        uint256 favoriteGPUTier;
        uint256 totalSavings; // From GPUDX discounts
        uint256 referralCount;
        uint256 socialPoints;
    }
    
    // State variables
    mapping(uint256 => Rental) public rentals;
    mapping(address => ProviderStats) public providerStats;
    mapping(address => UserStats) public userStats;
    mapping(address => uint256[]) public renterRentals;
    mapping(address => uint256[]) public providerRentals;
    mapping(address => bool) public authorizedArbitrators;
    
    uint256 public nextRentalId = 1;
    uint256 public platformFeePercent = 300; // 3% (300 basis points)
    uint256 public disputePeriod = 24 hours;
    uint256 public autoReleaseDelay = 48 hours;
    
    address public feeRecipient;
    IGPUDexTokenV2 public gpudexToken;
    
    // Utility validation metrics
    uint256 public totalRentalsProcessed;
    uint256 public totalVolumeProcessed;
    uint256 public totalDiscountsProvided;
    uint256 public totalGPUDXUtilization;
    uint256 public averageUserSatisfaction;
    
    // Social gamification
    mapping(string => uint256) public socialRewardRates; // activity => reward amount
    mapping(address => mapping(string => uint256)) public userAchievements;
    
    // Events
    event RentalCreated(
        uint256 indexed rentalId,
        address indexed renter,
        address indexed provider,
        string gpuType,
        uint256 totalAmount,
        uint256 discount
    );
    
    event RentalCompleted(
        uint256 indexed rentalId,
        uint256 performanceScore,
        uint256 providerEarnings,
        uint256 platformFee
    );
    
    event UtilityMetricsUpdated(
        uint256 totalRentals,
        uint256 totalVolume,
        uint256 totalDiscounts,
        uint256 utilizationRate
    );
    
    event SocialAchievementUnlocked(
        address indexed user,
        string achievement,
        uint256 rewardAmount
    );
    
    event ProviderVerified(address indexed provider, uint256 stakingTier);
    
    modifier onlyRenter(uint256 _rentalId) {
        require(rentals[_rentalId].renter == msg.sender, "Not the renter");
        _;
    }
    
    modifier onlyProvider(uint256 _rentalId) {
        require(rentals[_rentalId].provider == msg.sender, "Not the provider");
        _;
    }
    
    constructor(address _feeRecipient, address _gpudexToken) {
        feeRecipient = _feeRecipient;
        gpudexToken = IGPUDexTokenV2(_gpudexToken);
        authorizedArbitrators[msg.sender] = true;
        
        // Initialize social reward rates
        _initializeSocialRewards();
    }
    
    /**
     * @dev Initialize social reward rates for different activities
     */
    function _initializeSocialRewards() internal {
        socialRewardRates["first_rental"] = 50 * 10**18; // 50 GPUDX
        socialRewardRates["power_user"] = 200 * 10**18; // 200 GPUDX for 100+ hours
        socialRewardRates["loyal_customer"] = 100 * 10**18; // 100 GPUDX for 10+ rentals
        socialRewardRates["provider_debut"] = 75 * 10**18; // 75 GPUDX for first GPU listing
        socialRewardRates["high_rating"] = 25 * 10**18; // 25 GPUDX for 95%+ rating
        socialRewardRates["referral_bonus"] = 50 * 10**18; // 50 GPUDX per successful referral
    }
    
    /**
     * @dev Create a new GPU rental with enhanced features
     */
    function createRental(
        address _provider,
        string memory _gpuType,
        GPUTier _gpuTier,
        uint256 _pricePerHour,
        uint256 _duration,
        address _paymentToken,
        bool _autoRelease,
        bool _payWithGPUDX,
        address _referrer
    ) external returns (uint256) {
        require(_provider != address(0), "Invalid provider");
        require(_provider != msg.sender, "Cannot rent from yourself");
        require(_pricePerHour > 0, "Invalid price");
        require(_duration > 0, "Invalid duration");
        
        uint256 totalAmount = _pricePerHour * _duration;
        uint256 discountAmount = 0;
        
        // Apply GPUDX discount if user has tokens staked
        if (_payWithGPUDX) {
            discountAmount = gpudexToken.processGPURental(msg.sender, totalAmount);
            totalAmount -= discountAmount;
        }
        
        uint256 depositAmount = totalAmount + (totalAmount * 20 / 100); // 20% security deposit
        uint256 rentalId = nextRentalId++;
        
        rentals[rentalId] = Rental({
            rentalId: rentalId,
            renter: msg.sender,
            provider: _provider,
            gpuType: _gpuType,
            gpuTier: _gpuTier,
            pricePerHour: _pricePerHour,
            duration: _duration,
            totalAmount: totalAmount,
            depositAmount: depositAmount,
            discountApplied: discountAmount,
            paymentToken: _paymentToken,
            state: RentalState.Created,
            createdAt: block.timestamp,
            startedAt: 0,
            completedAt: 0,
            disputeDeadline: 0,
            providerEndpoint: "",
            accessCredentials: "",
            autoRelease: _autoRelease,
            performanceScore: 0,
            paidWithGPUDX: _payWithGPUDX
        });
        
        renterRentals[msg.sender].push(rentalId);
        providerRentals[_provider].push(rentalId);
        
        // Update metrics
        totalRentalsProcessed++;
        totalVolumeProcessed += (totalAmount + discountAmount);
        totalDiscountsProvided += discountAmount;
        if (_payWithGPUDX) totalGPUDXUtilization++;
        
        // Process referral if provided
        if (_referrer != address(0) && _referrer != msg.sender) {
            gpudexToken.processReferral(_referrer, msg.sender, socialRewardRates["referral_bonus"]);
            userStats[_referrer].referralCount++;
        }
        
        // Check for first rental achievement
        if (renterRentals[msg.sender].length == 1) {
            _awardAchievement(msg.sender, "first_rental");
        }
        
        emit RentalCreated(rentalId, msg.sender, _provider, _gpuType, totalAmount + discountAmount, discountAmount);
        
        return rentalId;
    }
    
    /**
     * @dev Fund a rental with payment
     */
    function fundRental(uint256 _rentalId) 
        external 
        onlyRenter(_rentalId)
        nonReentrant
    {
        Rental storage rental = rentals[_rentalId];
        require(rental.state == RentalState.Created, "Invalid state");
        
        // Transfer payment tokens to escrow
        IERC20(rental.paymentToken).safeTransferFrom(
            msg.sender,
            address(this),
            rental.depositAmount
        );
        
        rental.state = RentalState.Funded;
    }
    
    /**
     * @dev Provider starts the rental and provides access
     */
    function startRental(
        uint256 _rentalId,
        string memory _providerEndpoint,
        string memory _accessCredentials
    ) 
        external 
        onlyProvider(_rentalId)
    {
        Rental storage rental = rentals[_rentalId];
        require(rental.state == RentalState.Funded, "Not funded");
        
        rental.state = RentalState.Active;
        rental.startedAt = block.timestamp;
        rental.disputeDeadline = block.timestamp + disputePeriod;
        rental.providerEndpoint = _providerEndpoint;
        rental.accessCredentials = _accessCredentials;
        
        // Check if this is provider's first rental
        if (providerRentals[msg.sender].length == 1) {
            _awardAchievement(msg.sender, "provider_debut");
        }
    }
    
    /**
     * @dev Complete rental with performance rating
     */
    function completeRental(uint256 _rentalId, uint256 _performanceScore) 
        external
        onlyRenter(_rentalId)
        nonReentrant
    {
        require(_performanceScore >= 1 && _performanceScore <= 100, "Invalid performance score");
        
        Rental storage rental = rentals[_rentalId];
        require(rental.state == RentalState.Active, "Not active");
        
        rental.state = RentalState.Completed;
        rental.completedAt = block.timestamp;
        rental.performanceScore = _performanceScore;
        
        // Calculate and distribute payments
        uint256 platformFee = rental.totalAmount * platformFeePercent / 10000;
        uint256 baseProviderAmount = rental.totalAmount - platformFee;
        
        // Process provider earnings with potential boost
        uint256 finalProviderAmount = gpudexToken.processProviderEarnings(rental.provider, baseProviderAmount);
        
        // Transfer payments
        IERC20(rental.paymentToken).safeTransfer(rental.provider, finalProviderAmount);
        IERC20(rental.paymentToken).safeTransfer(feeRecipient, platformFee);
        
        // Refund security deposit
        uint256 refundAmount = rental.depositAmount - rental.totalAmount;
        IERC20(rental.paymentToken).safeTransfer(rental.renter, refundAmount);
        
        // Update stats
        _updateUserStats(rental.renter, rental);
        _updateProviderStats(rental.provider, rental.duration, _performanceScore);
        
        // Check for achievements
        _checkAchievements(rental.renter, rental.provider, _performanceScore);
        
        emit RentalCompleted(_rentalId, _performanceScore, finalProviderAmount, platformFee);
        emit UtilityMetricsUpdated(totalRentalsProcessed, totalVolumeProcessed, totalDiscountsProvided, (totalGPUDXUtilization * 100) / totalRentalsProcessed);
    }
    
    /**
     * @dev Update user statistics
     */
    function _updateUserStats(address _user, Rental memory _rental) internal {
        UserStats storage stats = userStats[_user];
        stats.totalSpent += (_rental.totalAmount + _rental.discountApplied);
        stats.totalHours += _rental.duration;
        stats.totalSavings += _rental.discountApplied;
        
        // Update favorite GPU tier (most used)
        stats.favoriteGPUTier = uint256(_rental.gpuTier);
    }
    
    /**
     * @dev Update provider statistics
     */
    function _updateProviderStats(address _provider, uint256 _hours, uint256 _performanceScore) internal {
        ProviderStats storage stats = providerStats[_provider];
        stats.totalRentals++;
        stats.totalHours += _hours;
        stats.totalEarnings += msg.value;
        
        // Update performance score (weighted average)
        if (stats.totalRentals == 1) {
            stats.averagePerformance = _performanceScore;
        } else {
            stats.averagePerformance = ((stats.averagePerformance * (stats.totalRentals - 1)) + _performanceScore) / stats.totalRentals;
        }
        
        stats.lastActiveAt = block.timestamp;
    }
    
    /**
     * @dev Check and award achievements
     */
    function _checkAchievements(address _renter, address _provider, uint256 _performanceScore) internal {
        UserStats storage renterStats = userStats[_renter];
        ProviderStats storage stats = providerStats[_provider];
        
        // Power user achievement (100+ hours)
        if (renterStats.totalHours >= 100 && userAchievements[_renter]["power_user"] == 0) {
            _awardAchievement(_renter, "power_user");
        }
        
        // Loyal customer (10+ rentals)
        if (renterRentals[_renter].length >= 10 && userAchievements[_renter]["loyal_customer"] == 0) {
            _awardAchievement(_renter, "loyal_customer");
        }
        
        // High-rating provider (95%+ average rating with 5+ rentals)
        if (stats.averagePerformance >= 95 && stats.totalRentals >= 5 && userAchievements[_provider]["high_rating"] == 0) {
            _awardAchievement(_provider, "high_rating");
        }
    }
    
    /**
     * @dev Award achievement to user
     */
    function _awardAchievement(address _user, string memory _achievement) internal {
        uint256 rewardAmount = socialRewardRates[_achievement];
        if (rewardAmount > 0) {
            userAchievements[_user][_achievement] = block.timestamp;
            userStats[_user].socialPoints += rewardAmount;
            
            gpudexToken.awardSocialReward(_user, _achievement, rewardAmount);
            emit SocialAchievementUnlocked(_user, _achievement, rewardAmount);
        }
    }
    
    /**
     * @dev Verify provider with staking requirement check
     */
    function verifyProvider(address _provider) external onlyOwner {
        (uint8 tier,,,,,) = gpudexToken.getUserTierInfo(_provider);
        require(tier > 0, "Provider must stake GPUDX tokens");
        
        providerStats[_provider].isVerified = true;
        providerStats[_provider].stakingTier = tier;
        
        emit ProviderVerified(_provider, tier);
    }
    
    /**
     * @dev Get comprehensive platform metrics for utility validation
     */
    function getPlatformMetrics() external view returns (
        uint256 totalRentals,
        uint256 totalVolume,
        uint256 totalDiscounts,
        uint256 gpudxUtilizationRate,
        uint256 avgSatisfaction,
        uint256 verifiedProviders,
        uint256 activeUsers
    ) {
        totalRentals = totalRentalsProcessed;
        totalVolume = totalVolumeProcessed;
        totalDiscounts = totalDiscountsProvided;
        gpudxUtilizationRate = totalRentalsProcessed > 0 ? (totalGPUDXUtilization * 100) / totalRentalsProcessed : 0;
        avgSatisfaction = averageUserSatisfaction;
        
        // Count verified providers and active users (simplified)
        // In production, these would be tracked more efficiently
        verifiedProviders = 0; // Would need separate tracking
        activeUsers = totalRentalsProcessed; // Simplified metric
    }
    
    /**
     * @dev Get user achievement status
     */
    function getUserAchievements(address _user) external view returns (
        uint256 firstRental,
        uint256 powerUser,
        uint256 loyalCustomer,
        uint256 providerDebut,
        uint256 highRating,
        uint256 socialPoints
    ) {
        firstRental = userAchievements[_user]["first_rental"];
        powerUser = userAchievements[_user]["power_user"];
        loyalCustomer = userAchievements[_user]["loyal_customer"];
        providerDebut = userAchievements[_user]["provider_debut"];
        highRating = userAchievements[_user]["high_rating"];
        socialPoints = userStats[_user].socialPoints;
    }
    
    /**
     * @dev Update social reward rates
     */
    function updateSocialRewardRate(string memory _activity, uint256 _rewardAmount) external onlyOwner {
        socialRewardRates[_activity] = _rewardAmount;
    }
    
    /**
     * @dev Update platform fee
     */
    function updatePlatformFee(uint256 _feePercent) external onlyOwner {
        require(_feePercent <= 1000, "Fee too high"); // Max 10%
        platformFeePercent = _feePercent;
    }
    
    /**
     * @dev Get rental details
     */
    function getRental(uint256 _rentalId) external view returns (Rental memory) {
        return rentals[_rentalId];
    }
    
    /**
     * @dev Get user statistics
     */
    function getUserStats(address _user) external view returns (UserStats memory) {
        return userStats[_user];
    }
    
    /**
     * @dev Get provider statistics
     */
    function getProviderStats(address _provider) external view returns (ProviderStats memory) {
        return providerStats[_provider];
    }
}

contracts/GPUDexToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";

/**
 * @title GPUDexToken (GPUDX)
 * @dev Platform governance token with staking rewards and fee distribution
 */
contract GPUDexToken is ERC20, ERC20Burnable, Pausable, Ownable, ERC20Permit, ERC20Votes {
    
    // Token distribution
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens
    uint256 public constant TEAM_ALLOCATION = 200_000_000 * 10**18; // 20%
    uint256 public constant INVESTORS_ALLOCATION = 150_000_000 * 10**18; // 15%
    uint256 public constant LIQUIDITY_ALLOCATION = 100_000_000 * 10**18; // 10%
    uint256 public constant TREASURY_ALLOCATION = 300_000_000 * 10**18; // 30%
    uint256 public constant STAKING_REWARDS_ALLOCATION = 200_000_000 * 10**18; // 20%
    uint256 public constant AIRDROP_ALLOCATION = 50_000_000 * 10**18; // 5%
    
    // Staking and rewards
    struct StakingInfo {
        uint256 amount;
        uint256 rewardDebt;
        uint256 stakedAt;
        uint256 lockUntil;
    }
    
    mapping(address => StakingInfo) public stakingInfo;
    mapping(address => bool) public isProvider;
    
    uint256 public totalStaked;
    uint256 public accRewardPerShare;
    uint256 public lastRewardBlock;
    uint256 public rewardPerBlock = 100 * 10**18; // 100 tokens per block
    
    // Fee distribution
    uint256 public totalFeesCollected;
    uint256 public feesPerTokenStaked;
    mapping(address => uint256) public feeDebt;
    
    // Governance
    uint256 public proposalCount;
    
    struct Proposal {
        uint256 id;
        address proposer;
        string description;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 startBlock;
        uint256 endBlock;
        bool executed;
        bool cancelled;
        mapping(address => bool) hasVoted;
        mapping(address => bool) voteChoice; // true = for, false = against
    }
    
    mapping(uint256 => Proposal) public proposals;
    uint256 public constant VOTING_DELAY = 7200; // 1 day (assuming 12 second blocks)
    uint256 public constant VOTING_PERIOD = 50400; // 7 days
    uint256 public constant PROPOSAL_THRESHOLD = 1_000_000 * 10**18; // 1M tokens to propose
    uint256 public constant QUORUM = 50_000_000 * 10**18; // 50M tokens for quorum
    
    // Events
    event Staked(address indexed user, uint256 amount, uint256 lockPeriod);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);
    event FeesDistributed(uint256 amount);
    event ProviderRegistered(address indexed provider);
    event ProviderUnregistered(address indexed provider);
    
    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string description,
        uint256 startBlock,
        uint256 endBlock
    );
    
    event VoteCast(
        address indexed voter,
        uint256 indexed proposalId,
        bool support,
        uint256 weight
    );
    
    event ProposalExecuted(uint256 indexed proposalId);
    
    constructor(address _initialOwner) 
        ERC20("GPUDex Token", "GPUDX") 
        ERC20Permit("GPUDex Token")
        Ownable()
    {
        _transferOwnership(_initialOwner);
        
        // Initial minting
        _mint(_initialOwner, TEAM_ALLOCATION);
        _mint(_initialOwner, TREASURY_ALLOCATION);
        _mint(address(this), STAKING_REWARDS_ALLOCATION); // For staking rewards
        
        lastRewardBlock = block.number;
    }
    
    /**
     * @dev Mint tokens to specific addresses (owner only)
     */
    function mint(address to, uint256 amount) public onlyOwner {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds max supply");
        _mint(to, amount);
    }
    
    /**
     * @dev Stake tokens for rewards and governance power
     */
    function stake(uint256 _amount, uint256 _lockDays) external whenNotPaused {
        require(_amount > 0, "Cannot stake 0");
        require(_lockDays <= 365, "Lock period too long");
        
        updateRewards();
        
        StakingInfo storage user = stakingInfo[msg.sender];
        
        // Claim pending rewards
        if (user.amount > 0) {
            uint256 pending = (user.amount * accRewardPerShare / 1e12) - user.rewardDebt;
            if (pending > 0) {
                _transfer(address(this), msg.sender, pending);
                emit RewardsClaimed(msg.sender, pending);
            }
        }
        
        // Transfer tokens to contract
        _transfer(msg.sender, address(this), _amount);
        
        // Update staking info
        user.amount += _amount;
        user.stakedAt = block.timestamp;
        user.lockUntil = block.timestamp + (_lockDays * 1 days);
        user.rewardDebt = user.amount * accRewardPerShare / 1e12;
        
        totalStaked += _amount;
        
        // Delegate voting power to self
        _delegate(msg.sender, msg.sender);
        
        emit Staked(msg.sender, _amount, _lockDays);
    }
    
    /**
     * @dev Unstake tokens
     */
    function unstake(uint256 _amount) external {
        StakingInfo storage user = stakingInfo[msg.sender];
        require(user.amount >= _amount, "Insufficient staked amount");
        require(block.timestamp >= user.lockUntil, "Tokens still locked");
        
        updateRewards();
        
        // Claim pending rewards
        uint256 pending = (user.amount * accRewardPerShare / 1e12) - user.rewardDebt;
        if (pending > 0) {
            _transfer(address(this), msg.sender, pending);
            emit RewardsClaimed(msg.sender, pending);
        }
        
        // Update staking info
        user.amount -= _amount;
        user.rewardDebt = user.amount * accRewardPerShare / 1e12;
        totalStaked -= _amount;
        
        // Transfer tokens back to user
        _transfer(address(this), msg.sender, _amount);
        
        emit Unstaked(msg.sender, _amount);
    }
    
    /**
     * @dev Claim staking rewards
     */
    function claimRewards() external {
        updateRewards();
        
        StakingInfo storage user = stakingInfo[msg.sender];
        uint256 pending = (user.amount * accRewardPerShare / 1e12) - user.rewardDebt;
        
        require(pending > 0, "No rewards to claim");
        
        user.rewardDebt = user.amount * accRewardPerShare / 1e12;
        _transfer(address(this), msg.sender, pending);
        
        emit RewardsClaimed(msg.sender, pending);
    }
    
    /**
     * @dev Update reward calculations
     */
    function updateRewards() public {
        if (block.number <= lastRewardBlock) {
            return;
        }
        
        if (totalStaked == 0) {
            lastRewardBlock = block.number;
            return;
        }
        
        uint256 multiplier = block.number - lastRewardBlock;
        uint256 reward = multiplier * rewardPerBlock;
        
        // Check if we have enough rewards in contract
        uint256 contractBalance = balanceOf(address(this)) - totalStaked;
        if (reward > contractBalance) {
            reward = contractBalance;
        }
        
        if (reward > 0) {
            accRewardPerShare += (reward * 1e12) / totalStaked;
        }
        
        lastRewardBlock = block.number;
    }
    
    /**
     * @dev Distribute platform fees to stakers
     */
    function distributeFees(uint256 _amount) external onlyOwner {
        require(_amount > 0, "No fees to distribute");
        require(totalStaked > 0, "No stakers");
        
        _transfer(msg.sender, address(this), _amount);
        
        feesPerTokenStaked += (_amount * 1e12) / totalStaked;
        totalFeesCollected += _amount;
        
        emit FeesDistributed(_amount);
    }
    
    /**
     * @dev Claim fee share
     */
    function claimFees() external {
        StakingInfo storage user = stakingInfo[msg.sender];
        require(user.amount > 0, "No staked tokens");
        
        uint256 pending = (user.amount * feesPerTokenStaked / 1e12) - feeDebt[msg.sender];
        require(pending > 0, "No fees to claim");
        
        feeDebt[msg.sender] = user.amount * feesPerTokenStaked / 1e12;
        _transfer(address(this), msg.sender, pending);
    }
    
    /**
     * @dev Register as GPU provider
     */
    function registerProvider() external {
        require(stakingInfo[msg.sender].amount >= 10_000 * 10**18, "Insufficient stake for provider"); // 10k tokens minimum
        isProvider[msg.sender] = true;
        emit ProviderRegistered(msg.sender);
    }
    
    /**
     * @dev Unregister as provider
     */
    function unregisterProvider() external {
        isProvider[msg.sender] = false;
        emit ProviderUnregistered(msg.sender);
    }
    
    /**
     * @dev Create governance proposal
     */
    function propose(string memory _description) external returns (uint256) {
        require(
            getVotes(msg.sender) >= PROPOSAL_THRESHOLD,
            "Insufficient voting power to propose"
        );
        
        uint256 proposalId = ++proposalCount;
        Proposal storage proposal = proposals[proposalId];
        
        proposal.id = proposalId;
        proposal.proposer = msg.sender;
        proposal.description = _description;
        proposal.startBlock = block.number + VOTING_DELAY;
        proposal.endBlock = proposal.startBlock + VOTING_PERIOD;
        
        emit ProposalCreated(
            proposalId,
            msg.sender,
            _description,
            proposal.startBlock,
            proposal.endBlock
        );
        
        return proposalId;
    }
    
    /**
     * @dev Vote on proposal
     */
    function castVote(uint256 _proposalId, bool _support) external {
        Proposal storage proposal = proposals[_proposalId];
        require(_proposalId > 0 && _proposalId <= proposalCount, "Invalid proposal");
        require(block.number >= proposal.startBlock, "Voting not started");
        require(block.number <= proposal.endBlock, "Voting ended");
        require(!proposal.hasVoted[msg.sender], "Already voted");
        
        uint256 weight = getVotes(msg.sender);
        require(weight > 0, "No voting power");
        
        proposal.hasVoted[msg.sender] = true;
        proposal.voteChoice[msg.sender] = _support;
        
        if (_support) {
            proposal.forVotes += weight;
        } else {
            proposal.againstVotes += weight;
        }
        
        emit VoteCast(msg.sender, _proposalId, _support, weight);
    }
    
    /**
     * @dev Execute proposal (if passed)
     */
    function executeProposal(uint256 _proposalId) external {
        Proposal storage proposal = proposals[_proposalId];
        require(_proposalId > 0 && _proposalId <= proposalCount, "Invalid proposal");
        require(block.number > proposal.endBlock, "Voting not ended");
        require(!proposal.executed && !proposal.cancelled, "Already executed or cancelled");
        require(proposal.forVotes > proposal.againstVotes, "Proposal failed");
        require(proposal.forVotes >= QUORUM, "Quorum not reached");
        
        proposal.executed = true;
        
        // Proposal execution logic would go here
        // For now, just emit event
        
        emit ProposalExecuted(_proposalId);
    }
    
    /**
     * @dev Get pending staking rewards
     */
    function pendingRewards(address _user) external view returns (uint256) {
        StakingInfo storage user = stakingInfo[_user];
        uint256 _accRewardPerShare = accRewardPerShare;
        
        if (block.number > lastRewardBlock && totalStaked != 0) {
            uint256 multiplier = block.number - lastRewardBlock;
            uint256 reward = multiplier * rewardPerBlock;
            uint256 contractBalance = balanceOf(address(this)) - totalStaked;
            if (reward > contractBalance) {
                reward = contractBalance;
            }
            _accRewardPerShare += (reward * 1e12) / totalStaked;
        }
        
        return (user.amount * _accRewardPerShare / 1e12) - user.rewardDebt;
    }
    
    /**
     * @dev Get pending fee rewards
     */
    function pendingFees(address _user) external view returns (uint256) {
        StakingInfo storage user = stakingInfo[_user];
        return (user.amount * feesPerTokenStaked / 1e12) - feeDebt[_user];
    }
    
    /**
     * @dev Pause contract (emergency)
     */
    function pause() public onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause contract
     */
    function unpause() public onlyOwner {
        _unpause();
    }
    
    /**
     * @dev Update reward per block
     */
    function updateRewardPerBlock(uint256 _rewardPerBlock) external onlyOwner {
        updateRewards();
        rewardPerBlock = _rewardPerBlock;
    }
    
    // Required overrides
    function _beforeTokenTransfer(address from, address to, uint256 amount)
        internal
        whenNotPaused
        override
    {
        super._beforeTokenTransfer(from, to, amount);
    }
    
    function _afterTokenTransfer(address from, address to, uint256 amount)
        internal
        override(ERC20, ERC20Votes)
    {
        super._afterTokenTransfer(from, to, amount);
    }
    
    function _mint(address to, uint256 amount)
        internal
        override(ERC20, ERC20Votes)
    {
        super._mint(to, amount);
    }
    
    function _burn(address account, uint256 amount)
        internal
        override(ERC20, ERC20Votes)
    {
        super._burn(account, amount);
    }
}

